// Personality (CLAUDE.md 5.4 order): highest trait wins if >= 50, ties to the lower index.
// 0 none, 1 playful, 2 curious, 3 calm, 4 sassy, 5 kind.
static inline uint8_t nl_personality(const uint8_t traits[5]) {
  uint8_t best = 0;
  for (uint8_t i = 1; i < 5; i++) if (traits[i] > traits[best]) best = i;
  return traits[best] >= 50 ? (uint8_t)(best + 1) : 0;
}

